async (page) => {
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    // Make the shell script executable
    await execPromise('chmod +x /tmp/workspace/run_cleanup.sh');

    // Run the cleanup script
    const { stdout, stderr } = await execPromise('/tmp/workspace/run_cleanup.sh');

    return {
      stdout: stdout,
      stderr: stderr
    };
  } catch (error) {
    return {
      error: error.message,
      stdout: error.stdout || '',
      stderr: error.stderr || ''
    };
  }
}

